using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioTransformGizmoAaValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static MashBoxStudioViewport view;static StudioModelEditor editor;static StudioModelDocument doc;static int checks,stage;static double next;static string report;static bool pending=true;static float previousSize;
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);checks++;}
 static object Get(string n)=>typeof(StudioModelEditor).GetField(n,F).GetValue(editor);
 static void Call(string n,params object[] args)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==args.Length).Invoke(editor,args);
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../transform-gizmo-aa-result.txt"));try{Check(Shader.Find("Hidden/MashBox/GizmoAntialias")&&!ShaderUtil.ShaderHasError(Shader.Find("Hidden/MashBox/GizmoAntialias")),"AA shader compilation");previousSize=StudioSettings.Current.handleSize;StudioSettings.Current.handleSize=1;doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(new StudioModelDocument.Node{name="Stem_Anchor",anchorType="Stem_Anchor"});editor=new StudioModelEditor(()=>{});editor.Load(doc);editor.SelectObject(0);view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();view.position=new Rect(80,80,700,600);view.Bind(editor.Scene);view.Show();view.LookAtDirect(Vector3.zero,Quaternion.Euler(25,35,0),3);SceneView.duringSceneGui+=Draw;next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static Color32[] Pixels(RenderTexture rt){var texture=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false,true);try{texture.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);texture.Apply();return texture.GetPixels32();}finally{Object.DestroyImmediate(texture);}}
 static void Save(Color32[] p,string name){var t=new Texture2D(700,600,TextureFormat.RGBA32,false,true);t.SetPixels32(p);t.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../gizmo-aa-"+name+".png")),t.EncodeToPNG());Object.DestroyImmediate(t);}
 static Vector2 Center(Color32[] p){double mass=0,x=0,y=0;for(int i=0;i<p.Length;i++){mass+=p[i].a;x+=(i%700)*p[i].a;y+=(i/700)*p[i].a;}return new Vector2((float)(x/mass),(float)(y/mass));} static int Partial(Color32[] p){int max=p.Max(c=>(int)c.a);return p.Count(c=>c.a>2&&c.a<max*.9);}
 static void Draw(SceneView scene){if(!pending||scene!=view||Event.current.type!=EventType.Repaint)return;pending=false;var rt=new RenderTexture(700,600,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);rt.Create();var old=RenderTexture.active;var oldTarget=view.camera.targetTexture;var oldRect=view.camera.pixelRect;GL.PushMatrix();try{view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,700,600);Handles.SetCamera(new Rect(0,0,700,600),view.camera);RenderTexture.active=rt;GL.Clear(true,true,Color.clear);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;
 if(stage==0){((System.Collections.Generic.HashSet<int>)Get("objects")).Clear();Call("DrawAnchorMarkers",view);var anchors=Pixels(rt);Check(anchors.Count(c=>c.b>c.g*1.2&&c.b>c.r*1.3&&c.b>40)>0,"Anchor forward arm is not blue");Check(anchors.Count(c=>c.r>c.g*1.3&&c.g>c.b*1.5&&c.r>40)>10,"Anchor ring/other arms must be orange");var origin=(Vector2)view.camera.WorldToScreenPoint(Vector3.zero); var forward=((Vector2)view.camera.WorldToScreenPoint(Vector3.forward)-origin).normalized; int positiveBlue=0,negativeBlue=0; for(int pixel=0;pixel<anchors.Length;pixel++){var c=anchors[pixel];if(c.b>c.g*1.2&&c.b>c.r*1.3&&c.b>40){float side=Vector2.Dot(new Vector2(pixel%700+.5f,pixel/700+.5f)-origin,forward);if(side>3)positiveBlue++;if(side< -3)negativeBlue++;}} Check(positiveBlue>0&&negativeBlue==0,"Blue must be restricted to positive Z"); Save(anchors,"anchor-z");}
 else{var tool=(Tool)new[]{Tool.Move,Tool.Rotate,Tool.Scale}[(stage-1)%3];typeof(StudioModelEditor).GetField("tool",F).SetValue(editor,tool);Handles.color=Color.white;using(new Handles.DrawingScope(Matrix4x4.identity)){if(tool==Tool.Move)Call("DrawMoveHandle",Vector3.zero,Quaternion.identity,1f);else if(tool==Tool.Rotate)typeof(StudioModelEditor).GetMethod("DrawSizedRotationHandle",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{Handles.RotationHandleIds.@default,Quaternion.identity,Vector3.zero,1f});else Handles.ScaleHandle(Vector3.one,Vector3.zero,Quaternion.identity,HandleUtility.GetHandleSize(Vector3.zero));}
 var before=Pixels(rt);int hot=GUIUtility.hotControl;var cameraPose=view.camera.transform.localToWorldMatrix;Call("AntialiasTransformGizmo",Vector3.zero,HandleUtility.GetHandleSize(Vector3.zero)*1.35f);Check(RenderTexture.active==rt,"AA did not restore active target");var after=Pixels(rt);Save(before,tool+"-raw-"+view.orthographic);Save(after,tool+"-smooth-"+view.orthographic);foreach(string field in new[]{"gizmoAaInput","gizmoAaOutput"}){var debug=Get(field) as RenderTexture;if(debug){RenderTexture.active=debug;var tex=new Texture2D(debug.width,debug.height,TextureFormat.RGBA32,false,true);tex.ReadPixels(new Rect(0,0,debug.width,debug.height),0,0);tex.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+field+".png")),tex.EncodeToPNG());Object.DestroyImmediate(tex);}}RenderTexture.active=rt;Check(before.Count(c=>c.a>0)>100,"Native "+tool+" did not render");Check(!before.SequenceEqual(after),"AA did not affect "+tool);Check(Vector2.Distance(Center(before),Center(after))<1.5f,"AA moved the rendered gizmo");Check(Partial(after)>Partial(before),"AA did not increase fractional edge coverage for "+tool+": "+Partial(before)+"/"+Partial(after));double coverageBefore=before.Sum(c=>(double)c.a),coverageAfter=after.Sum(c=>(double)c.a);Check(coverageAfter>coverageBefore*.75&&coverageAfter<coverageBefore*1.25,"AA changed handle coverage excessively for "+tool);Check(GUIUtility.hotControl==hot&&view.camera.transform.localToWorldMatrix==cameraPose,"AA changed input control/camera");Check(editor.Transforms[0].position==Vector3.zero&&doc.nodes[0].position==Vector3.zero,"AA changed anchor transform");var buffer=Get("gizmoAaInput") as RenderTexture;Check(buffer&&buffer.width<rt.width&&buffer.height<rt.height,"AA is not bounded to a small overlay tile");Call("AntialiasTransformGizmo",Vector3.zero,HandleUtility.GetHandleSize(Vector3.zero)*1.35f);Check(ReferenceEquals(buffer,Get("gizmoAaInput")),"AA reallocates unchanged buffers");Save(before,tool+"-raw-"+view.orthographic);Save(after,tool+"-smooth-"+view.orthographic);}
 }catch(Exception e){Finish(e.ToString());}finally{view.camera.targetTexture=oldTarget;view.camera.pixelRect=oldRect;Handles.SetCamera(view.camera);GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(rt);}}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.3;try{if(pending){view.MarkDirty(MashBoxStudioViewport.DirtyState.All);view.SendEvent(new Event{type=EventType.Layout});view.SendEvent(new Event{type=EventType.Repaint});return;}if(++stage==7){Finish("PASS "+checks+" native rendered anchor/transform-AA checks");return;}if(stage==4)view.orthographic=true;pending=true;view.MarkDirty(MashBoxStudioViewport.DirtyState.All);}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string result){EditorApplication.update-=Tick;SceneView.duringSceneGui-=Draw;StudioSettings.Current.handleSize=previousSize;File.WriteAllText(report,result);bool success=result.StartsWith("PASS");EditorApplication.delayCall+=()=>{if(view)view.Close();editor?.Dispose();if(doc)Object.DestroyImmediate(doc);EditorApplication.Exit(success?0:1);};}
}
